CREATE TABLE processes (
    process_id VARCHAR(10) PRIMARY KEY,
    process_name VARCHAR(50) NOT NULL
);

INSERT INTO processes (process_id, process_name) VALUES ('M1', 'Process M1'), ('M2', 'Process M2'), ('M3', 'Process M3'), ('M4', 'Process M4');

CREATE TABLE equipment (
    equipment_id VARCHAR(10) PRIMARY KEY,
    equipment_name VARCHAR(50) NOT NULL
);

INSERT INTO equipment (equipment_id, equipment_name) VALUES ('M1', 'Equipment M1'), ('M2', 'Equipment M2'), ('M3', 'Equipment M3'), ('M4', 'Equipment M4'), ('B0', 'Buffer B0'), ('B1', 'Buffer B1'), ('B2', 'Buffer B2'), ('B3', 'Buffer B3');

CREATE TABLE sensors (
    sensor_id VARCHAR(50) PRIMARY KEY,
    sensor_type VARCHAR(50) NOT NULL,
    equipment_id VARCHAR(10),
    FOREIGN KEY (equipment_id) REFERENCES equipment(equipment_id)
);

INSERT INTO sensors (sensor_id, sensor_type, equipment_id) VALUES ('buffer_levels', 'Buffer Level', 'B0'), ('buffer_levels', 'Buffer Level', 'B1'), ('buffer_levels', 'Buffer Level', 'B2'), ('buffer_levels', 'Buffer Level', 'B3'), ('processing_time_s', 'Processing Time', 'M1'), ('processing_time_s', 'Processing Time', 'M2'), ('processing_time_s', 'Processing Time', 'M3'), ('processing_time_s', 'Processing Time', 'M4'), ('availability', 'Availability', 'M1'), ('availability', 'Availability', 'M2'), ('availability', 'Availability', 'M3'), ('availability', 'Availability', 'M4'), ('mttr_s', 'Mean Time to Repair', 'M1'), ('mttr_s', 'Mean Time to Repair', 'M2'), ('mttr_s', 'Mean Time to Repair', 'M3'), ('mttr_s', 'Mean Time to Repair', 'M4'), ('work_power_kw', 'Work Power', 'M1'), ('work_power_kw', 'Work Power', 'M2'), ('work_power_kw', 'Work Power', 'M3'), ('work_power_kw', 'Work Power', 'M4'), ('idle_power_kw', 'Idle Power', 'M1'), ('idle_power_kw', 'Idle Power', 'M2'), ('idle_power_kw', 'Idle Power', 'M3'), ('idle_power_kw', 'Idle Power', 'M4');

CREATE TABLE data_sources (
    source_id SERIAL PRIMARY KEY,
    source_type VARCHAR(50) NOT NULL,
    description TEXT
);

INSERT INTO data_sources (source_type, description) VALUES ('Input Stream', '1 part every 45 seconds'), ('Real-time Measurements', 'Manufacturing period measurements');

CREATE TABLE goals (
    goal_id SERIAL PRIMARY KEY,
    goal_description TEXT NOT NULL
);

INSERT INTO goals (goal_description) VALUES ('Evaluate line capacity (throughput)'), ('Monitor WIP (buffer levels)'), ('Optimize energy consumption per part'), ('Monitor machine availability and downtime');

CREATE TABLE monitoring_data (
    data_id SERIAL PRIMARY KEY,
    sensor_id VARCHAR(50),
    timestamp TIMESTAMP NOT NULL,
    value NUMERIC,
    FOREIGN KEY (sensor_id) REFERENCES sensors(sensor_id)
);

CREATE TABLE simulation_parameters (
    param_id SERIAL PRIMARY KEY,
    parameter_name VARCHAR(50) NOT NULL,
    value NUMERIC,
    description TEXT
);

INSERT INTO simulation_parameters (parameter_name, value, description) VALUES ('inter_arrival_s', 45, 'Time between parts arrival'), ('process_time_s', 30, 'Processing time for each machine'), ('availability', 95, 'Machine availability percentage'), ('mttr_s', 600, 'Mean Time to Repair in seconds'), ('work_power_kw', 10, 'Work power in kilowatts'), ('idle_power_kw', 2, 'Idle power in kilowatts');
